<?php
$pageTitle='Panel administrativo';$basePath='../';$adminScripts=true;$adminActive='resumen';require_once __DIR__.'/../auth.php';requireAdmin('../login.php','../usuario/index.php');require_once __DIR__.'/../firebase-data.php';
$period=normalizePeriod($_GET['period']??null,['today','7days','month','year','all'],'month');[$start,$end,$tz]=adminPeriodBounds($period);
$rawUsers=firebaseRead(fn(FirebaseReadService $f)=>$f->rtdb('usuarios'));$users=is_array($rawUsers)?$rawUsers:[];$allOrders=array_values(array_filter(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('pedidos')), 'is_array'));$products=normalizeProducts(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('productos')));$allReservations=array_values(array_filter(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('reservas')), 'is_array'));$messages=array_values(array_filter(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('mensajes')), 'is_array'));$machine=firebaseRead(fn(FirebaseReadService $f)=>$f->rtdb('dispensador/principal'));
$orders=array_values(array_filter($allOrders,fn($o)=>inAdminPeriod($o['fechaCreacion']??null,$start,$end,$tz)));$sales=array_values(array_filter($orders,'isValidSale'));$reservations=array_values(array_filter($allReservations,fn($r)=>inAdminPeriod($r['fechaSolicitada']??$r['fechaCreacion']??null,$start,$end,$tz)));$blocked=count(array_filter($users,fn($u)=>is_array($u)&&($u['bloqueado']??false)===true));$total=array_sum(array_map(fn($o)=>(float)($o['total']??0),$sales));$activeReservations=count(array_filter($reservations,fn($r)=>in_array(strtolower((string)($r['estado']??'')),['pendiente','aceptada'],true)));$activePromos=count(array_filter($messages,fn($m)=>($m['activo']??false)===true&&($m['tipo']??'')==='promocion'));
$buyers=[];$daily=[];$payment=[];$origin=[];$productStats=[];foreach($sales as $o){$date=firebaseDate($o['fechaCreacion']??null)?->setTimezone($tz);if($date){$key=$date->format('Y-m-d');$daily[$key]['sales']=($daily[$key]['sales']??0)+(float)($o['total']??0);$daily[$key]['orders']=($daily[$key]['orders']??0)+1;}$payment[(string)($o['metodoPago']??'Sin datos')]=($payment[(string)($o['metodoPago']??'Sin datos')]??0)+1;$org=orderOrigin($o);$origin[$org]=($origin[$org]??0)+1;foreach(orderItems($o) as $item)if(is_array($item)){$name=(string)($item['nombre']??'Sin detalle');$productStats[$name]=($productStats[$name]??0)+(int)($item['cantidad']??1);}$uid=(string)($o['usuarioId']??'');if($uid!==''&&strtolower((string)($o['tipoUsuario']??''))!=='fisico'&&strtolower((string)($o['origenPedido']??''))!=='pulsador'){$buyers[$uid]['count']=($buyers[$uid]['count']??0)+1;$buyers[$uid]['total']=($buyers[$uid]['total']??0)+(float)($o['total']??0);$buyers[$uid]['last']=max($buyers[$uid]['last']??0,$date?->getTimestamp()??0);}}
uasort($buyers,fn($a,$b)=>$b['total']<=>$a['total']);ksort($daily);$daily=array_slice($daily,-14,14,true);arsort($productStats);$userIdsWithOrders=array_unique(array_filter(array_map(fn($o)=>(string)($o['usuarioId']??''),$allOrders)));$maxDaily=max(array_map(fn($d)=>max((float)$d['sales'],1),$daily)?:[1]);
require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';require __DIR__.'/../admin-nav.php';
