<main id="contenido" class="admin-page"><section class="admin-head admin-head--with-nav"><div class="container"><div><span class="eyebrow eyebrow--light">Centro de decisiones</span><h1>Resumen administrativo</h1><p>Indicadores y tendencias calculados con datos reales del período.</p></div><span class="status-pill <?=firebaseReadFailed()?'status-pill--idle':'status-pill--active'?>">● <?=firebaseReadFailed()?'Sin datos':'Lectura activa'?></span></div></section><section class="section section--cream"><div class="container"><form class="admin-periods" method="get" aria-label="Período del análisis"><?php foreach(['today'=>'Hoy','7days'=>'Últimos 7 días','month'=>'Este mes','year'=>'Este año','all'=>'Todos'] as $key=>$label):?><button name="period" value="<?=$key?>" class="<?=$period===$key?'is-active':''?>"><?=$label?></button><?php endforeach;?></form><div class="admin-metrics admin-metrics--wide"><article><span>Ventas</span><strong><?=firebaseReadFailed()?'Sin datos':h(money($total))?></strong><small><?=count($sales)?> ventas válidas</small></article><article><span>Pedidos</span><strong><?=firebaseReadFailed()?'Sin datos':count($orders)?></strong><small>En el período</small></article><article><span>Usuarios</span><strong><?=firebaseReadFailed()?'Sin datos':count($users)?></strong><small><?=$blocked?> bloqueados</small></article><article><span>Con compras</span><strong><?=firebaseReadFailed()?'Sin datos':count($userIdsWithOrders)?></strong><small><?=max(0,count($users)-count($userIdsWithOrders))?> sin compras</small></article><article><span>Reservas activas</span><strong><?=firebaseReadFailed()?'Sin datos':$activeReservations?></strong><small><?=count($reservations)?> en el período</small></article><article><span>Promociones</span><strong><?=firebaseReadFailed()?'Sin datos':$activePromos?></strong><small>Activas</small></article><article><span>Productos</span><strong><?=firebaseReadFailed()?'Sin datos':count($products)?></strong><small>Catálogo</small></article><article><span>Dispensador</span><strong><?=h(is_array($machine)?($machine['estado']??'Sin datos'):'Sin datos')?></strong><small><?=h(is_array($machine)?($machine['productoactual']??'Producto sin datos'):'RTDB')?></small></article></div>
<div class="analytics-grid"><section class="analytics-card analytics-card--wide"><div class="analytics-head"><div><small>Tendencia</small><h2>Ventas y pedidos por día</h2></div><span>Últimos <?=count($daily)?> días con actividad</span></div><?php if(!$daily):?><p class="chart-empty">Sin ventas para graficar.</p><?php else:?><div class="bar-chart"><?php foreach($daily as $date=>$data):?><div><span style="height:<?=max(4,round(((float)$data['sales']/$maxDaily)*100))?>%" title="<?=h(money($data['sales']))?>"></span><b><?=$data['orders']?></b><small><?=h((new DateTimeImmutable($date))->format('d/m'))?></small></div><?php endforeach;?></div><?php endif;?></section><section class="analytics-card"><small>Distribución</small><h2>Métodos de pago</h2><ul class="metric-bars"><?php foreach($payment as $k=>$v):?><li><span><?=h($k)?></span><i style="--value:<?=count($sales)?round($v/count($sales)*100):0?>%"></i><b><?=$v?></b></li><?php endforeach;?><?php if(!$payment):?><li>Sin datos</li><?php endif;?></ul></section><section class="analytics-card"><small>Canales</small><h2>Origen de ventas</h2><ul class="metric-bars"><?php foreach($origin as $k=>$v):?><li><span><?=h($k)?></span><i style="--value:<?=count($sales)?round($v/count($sales)*100):0?>%"></i><b><?=$v?></b></li><?php endforeach;?><?php if(!$origin):?><li>Sin datos</li><?php endif;?></ul></section><section class="analytics-card"><small>Productos</small><h2>Más vendidos</h2><ol class="ranking-list"><?php foreach(array_slice($productStats,0,5,true) as $name=>$qty):?><li><span><?=h($name)?></span><b><?=$qty?></b></li><?php endforeach;?><?php if(!$productStats):?><li>Sin datos</li><?php endif;?></ol></section></div>
<section class="analytics-card top-users"><div class="analytics-head"><div><small>Ranking</small><h2>Top usuarios</h2></div><span>Excluye ventas físicas y pulsador</span></div><?php if(!$buyers):?><p class="chart-empty">Sin compras de usuarios en el período.</p><?php else:?><ol class="top-users__list"><?php $position=0;foreach(array_slice($buyers,0,10,true) as $uid=>$stat):$position++;$u=is_array($users[$uid]??null)?$users[$uid]:[];?><li><b>#<?=$position?></b><div><strong><?=h($u['nombre']??$uid)?></strong><small><?=h($u['email']??'Sin email')?></small></div><span><?=$stat['count']?> compras</span><span><?=h(money($stat['total']))?></span><time><?=h($stat['last']?displayDate($stat['last']):'Sin fecha')?></time></li><?php endforeach;?></ol><?php endif;?></section></div></section></main>
